// Fog Patch
// status: planned
// requires: keyword action BecomeBlocked
// Cast this spell only during the declare blockers step.
// Attacking creatures become blocked. (This spell works on creatures that can't be blocked.)
#[allow(unused_imports)] use cantrip_api::*;
fn ability_0_if(q: &dyn Query, asker: &Asker) -> bool { q.state().turn.step() == Step::DeclareBlockers }
fn ability_1(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> { let asker = &Asker::new(item.object, item.controller);
planned!("keyword-action-become-blocked" => for object in { let q: &dyn Query = g; (q.state().battlefield().iter().copied().filter(|&id| ((q.state().attackers.iter().any(|a| a.id == id) || q.was_attacking(id)) && q.chars(id).is(CardType::Creature))).collect::<Vec<ObjectId>>()).into_iter().filter(|&o| q.state().obj(o).became.is_none()).collect::<Vec<ObjectId>>() } { g.become_blocked(object); });
g.end_sentence();
 Ok(()) }

